record.field:
portal_group = env.ref('base.group_portal')
admin_group = env.ref('base.group_system')

# Process records: Skip ID 1 AND anyone with Admin rights, convert others
targets = records.filtered(lambda r: r.id != 1 and admin_group not in r.group_ids)

if targets:
    for record in targets:
        # Odoo 19: Use 'group_ids' to set the user to Portal group only
        record.write({'group_ids': [(6, 0, [portal_group.id])]})

    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Success',
            'message': f'Successfully converted {len(targets)} users to Portal.',
            'type': 'success',
            'sticky': False,
            'next': {'type': 'ir.actions.client', 'tag': 'reload'},
        }
    }
else:
    # If only Admins were selected, just reload silently
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
